+// CMove with values in registers, condition coming from a VectorTest.
+//
+// The two rules above only cover the canonical "cond ? 1 : 0" boolean
+// materialization, where vcpop.m already produces the result. Everything
+// else needs the mask test lowered into a GPR first, so that the ordinary
+// integer cmove can be used against zr:
+//
+//   anytrue: vcpop.m t0, op1                  // t0 != 0 iff some element is set
+//   alltrue: vcpop.m t0, op1; sub t0, t0, vl  // t0 == 0 iff every element is set
+//
+// $cop is restricted to eq/ne by cmpOpEqNe, which is all a VectorTest can
+// produce, so only anytrue/alltrue need to be split into separate rules.
+
+instruct cmovI_vtest_anytrue_reg(iRegINoSp dst, iRegI src, cmpOpEqNe cop, vRegMask op1, vRegMask op2) %{
+  predicate(static_cast<const VectorTestNode*>(n->in(1)->in(2))->get_predicate() == BoolTest::ne);
+  match(Set dst (CMoveI (Binary cop (VectorTest op1 op2)) (Binary dst src)));
+  format %{ "CMoveI $dst, (vectortest $cop $op1 $op2), $dst, $src\t#@cmovI_vtest_anytrue_reg" %}
+  ins_encode %{
+    vectorTest(masm, t0, as_VectorRegister($op1$$reg),
+               Matcher::vector_element_basic_type(this, $op1),
+               Matcher::vector_length(this, $op1), BoolTest::ne);
+    __ enc_cmove($cop$$cmpcode, t0, zr,
+                 as_Register($dst$$reg), as_Register($src$$reg));
+  %}
+  ins_pipe(pipe_slow);
+%}
+
+instruct cmovI_vtest_alltrue_reg(iRegINoSp dst, iRegI src, cmpOpEqNe cop, vRegMask op1, vRegMask op2) %{
+  predicate(static_cast<const VectorTestNode*>(n->in(1)->in(2))->get_predicate() == BoolTest::overflow);
+  match(Set dst (CMoveI (Binary cop (VectorTest op1 op2)) (Binary dst src)));
+  format %{ "CMoveI $dst, (vectortest $cop $op1 $op2), $dst, $src\t#@cmovI_vtest_alltrue_reg" %}
